export function cache(e,t,n){if(n.get){let e=n.get;n.get=function(){let n=e.call(this);return Object.defineProperty(this,t,{value:n}),n}}else if("function"==typeof n.value){let e=n.value;return{get(){let n=new Map;function l(...t){let l=t.length>0?t[0]:"value";if(n.has(l))return n.get(l);let r=e.apply(this,t);return n.set(l,r),r}return Object.defineProperty(this,t,{value:l}),l}}}}